from backend.response import FormattedResponse
from config import config
from backend.permissions import AdminOrAnonymousReadOnly


class ConfigView(APIView):
    throttle_scope = "config"
    permission_classes = (AdminOrAnonymousReadOnly,)

    def get(self, request, name=None):
        if name is None:
            if request.user.is_superuser:
                return FormattedResponse(config.get_all())
            return FormattedResponse(config.get_all_non_sensitive())
        if not config.is_sensitive(name) or request.is_superuser:
            return FormattedResponse(config.get(name))
        return FormattedResponse(status=HTTP_403_FORBIDDEN)

    def post(self, request, name):
        if "value" not in request.data:
            return FormattedResponse(status=HTTP_400_BAD_REQUEST)
        config.set(name, request.data.get("value"))
        return FormattedResponse()

    def patch(self, request, name):
        if "value" not in request.data:
            return FormattedResponse(status=HTTP_400_BAD_REQUEST)
        if config.get(name) is not None and isinstance(config.get(name), list):
            config.set("name", config.get(name).append(request.data["value"]))
            return FormattedResponse()
        config.set(name, request.data.get("value"))
        return FormattedResponse()

import requests
from django.conf import settings
from requests.auth import HTTPBasicAuth
from rest_framework.status import HTTP_401_UNAUTHORIZED, HTTP_403_FORBIDDEN

from backend.exceptions import FormattedException


def handle_request(method, path, **kwargs):
    response = requests.request(method, f"{settings.POLARIS_URL}/{path}",
                                auth=HTTPBasicAuth(settings.POLARIS_USERNAME, settings.POLARIS_PASSWORD), **kwargs)
    if 200 <= response.status_code < 300:
        return response.json()
    elif response.status_code == HTTP_401_UNAUTHORIZED:
        raise FormattedException(status_code=HTTP_401_UNAUTHORIZED, m='polaris_unauthorized')
    elif response.status_code == HTTP_403_FORBIDDEN:
        raise FormattedException(status_code=HTTP_403_FORBIDDEN, m='polaris_permission_denied')
    else:
        raise FormattedException(m='polaris_error', d=response.json())


def get(path, **kwargs):
    return handle_request('GET', path, **kwargs)


def post(path, **kwargs):
    return handle_request('POST', path, **kwargs)


def put(path, **kwargs):
    return handle_request('PUT', path, **kwargs)


def delete(path, **kwargs):
    return handle_request('DELETE', path, **kwargs)


