        if self.request.user.is_superuser and not self.request.user.should_deny_admin():
            return Team.objects.order_by("id").prefetch_related(
                "solves",
                "members",
                "hints_used",
                "solves__challenge",
                "solves__score",
                "solves__solved_by",
            )
        return (
            Team.objects.filter(is_visible=True)
            .order_by("id")
            .prefetch_related(
                "solves",
                "members",
                "hints_used",
                "solves__challenge",
                "solves__score",
                "solves__solved_by",
            )
        )


