class JoinTeamView(APIView):
    permission_classes = (IsAuthenticated & ~HasTeam & TeamsEnabled,)
    throttle_scope = "team_join"

    def post(self, request):
        if not config.get("enable_team_join"):
            return FormattedResponse(m="join_disabled", status=HTTP_403_FORBIDDEN)
        name = request.data.get("name")
        password = request.data.get("password")
        team_join_attempt.send(sender=self.__class__, user=request.user, name=name)
        if name and password:
            try:
                team = get_object_or_404(Team, name=name)
                if team.password != password:
                    team_join_reject.send(sender=self.__class__, user=request.user, name=name)
                    raise FormattedException(m='invalid_team_password', status_code=HTTP_403_FORBIDDEN)
            except Http404:
                team_join_reject.send(sender=self.__class__, user=request.user, name=name)
                raise FormattedException(m='invalid_team', status_code=HTTP_404_NOT_FOUND)
            team_size = int(config.get('team_size'))
            if not request.user.is_staff and not team.size_limit_exempt and 0 < team_size <= team.members.count():
                return FormattedResponse(m='team_full', status=HTTP_403_FORBIDDEN)
            request.user.team = team
            request.user.save()
            team_join.send(sender=self.__class__, user=request.user, team=team)
            return FormattedResponse()
        return FormattedResponse(m='joined_team', status=HTTP_400_BAD_REQUEST)


class LeaveTeamView(APIView):
    """
    Remove the authenticated user from a team.
    """

    permission_classes = (IsAuthenticated & HasTeam & TeamsEnabled,)

    def post(self, request):
        if not config.get('enable_team_leave'):
            return FormattedResponse(m='leave_disabled', status=HTTP_403_FORBIDDEN)
        if Solve.objects.filter(solved_by=request.user).exists():
            return FormattedResponse(m='challenge_solved', status=HTTP_403_FORBIDDEN)
        if request.user.team.owner == request.user:
            if Member.objects.filter(team=request.user.team).count() > 1:
                return FormattedResponse(m='cannot_leave_team_ownerless', status=HTTP_403_FORBIDDEN)
            else:
                request.user.team.delete()
        request.user.team = None
        request.user.save()
        return FormattedResponse()

from asgiref.sync import async_to_sync
from channels.layers import get_channel_layer
from django.db.models.signals import post_save
from django.dispatch import receiver

from announcements.models import Announcement
from announcements.serializers import AnnouncementSerializer
from backend.signals import flag_score, flag_reject, use_hint, team_join
from config import config


def get_team_channel(user):
    return f'team.{user.team.id}'


def send(user, data):
    channel_layer = get_channel_layer()
    async_to_sync(channel_layer.group_send)(get_team_channel(user), data)


def broadcast(data):
    channel_layer = get_channel_layer()
    async_to_sync(channel_layer.group_send)('event', data)


@receiver(flag_score)
def on_flag_score(user, team, challenge, flag, solve, **kwargs):
    if not config.get('enable_solve_broadcast'):
        return
    broadcast({
        'type': 'send_json',
        'event_code': 1,
        'user': user.id,
        'username': user.username,
        'challenge_id': challenge.id,
        'challenge_name': challenge.name,
        'challenge_score': solve.score.points,
        'team': team.id,
        'team_name': team.name,
    })


@receiver(flag_reject)
def on_flag_reject(user, team, challenge, flag, **kwargs):
    send(user, {
        'type': 'send_json',
        'event_code': 2,
        'user': user.id,
        'username': user.username,
        'challenge_id': challenge.id,
        'challenge_name': challenge.name,
        'team': team.id,
        'team_name': team.name,
    })


@receiver(use_hint)
def on_use_hint(user, team, hint, **kwargs):
    send(user, {
        'type': 'send_json',
        'event_code': 3,
        'user': user.id,
        'username': user.username,
        'team': team.id,
        'team_name': team.name,
        'hint_name': hint.name,
        'hint_penalty': hint.penalty,
        'hint_text': hint.text,
        'challenge': hint.challenge.name,
    })


@receiver(team_join)
def on_team_join(user, team, **kwargs):
    send(user, {
        'type': 'send_json',
        'event_code': 4,
        'user': user.id,
        'username': user.username,
        'team': team.id,
        'team_name': team.name,
    })


@receiver(post_save, sender=Announcement)
def on_announcement_create(sender, instance, **kwargs):
    data = AnnouncementSerializer(instance).data
    data['type'] = 'send_json'
    data['event_code'] = 5
    broadcast(data)

