    AdminTeamSerializer,
    ListTeamSerializer,
)


class SelfView(RetrieveUpdateAPIView):
    serializer_class = SelfTeamSerializer
    permission_classes = (IsAuthenticated & IsTeamOwnerOrReadOnly & ReadOnlyBot,)
    throttle_scope = "self"
    pagination_class = None

    def get_object(self):
        if self.request.user.team is None:
            raise Http404()
        return (
            Team.objects.order_by("id")
            .prefetch_related(
                "solves",
                "members",
                "hints_used",
                "solves__challenge",
                "solves__score",
                "solves__solved_by",
            ).get(id=self.request.user.team.id)
        )


class TeamViewSet(AdminListModelViewSet):
    permission_classes = (AdminOrReadOnlyVisible,)
    throttle_scope = "team"
    serializer_class = TeamSerializer
    admin_serializer_class = AdminTeamSerializer
    list_serializer_class = ListTeamSerializer
    list_admin_serializer_class = ListTeamSerializer
    search_fields = ["name"]
    filter_backends = [filters.SearchFilter]

    def get_queryset(self):
        if self.action == "list":
            if self.request.user.is_superuser:
                return Team.objects.order_by("id").prefetch_related("members")
            return Team.objects.filter(is_visible=True).order_by("id").prefetch_related("members")
        if self.request.user.is_superuser and not self.request.user.should_deny_admin():
            return Team.objects.order_by("id").prefetch_related(
                "solves",
                "members",
                "hints_used",
                "solves__challenge",
                "solves__score",
                "solves__solved_by",
            )
        return (
            Team.objects.filter(is_visible=True)
            .order_by("id")
            .prefetch_related(
                "solves",
                "members",
                "hints_used",
                "solves__challenge",
                "solves__score",
                "solves__solved_by",
            )
        )


class CreateTeamView(CreateAPIView):
    serializer_class = CreateTeamSerializer
    model = Team
    permission_classes = (IsAuthenticated & ~HasTeam,)
    throttle_scope = "team_create"


class JoinTeamView(APIView):
    permission_classes = (IsAuthenticated & ~HasTeam & TeamsEnabled,)
    throttle_scope = "team_join"

    def post(self, request):
        if not config.get("enable_team_join"):
            return FormattedResponse(m="join_disabled", status=HTTP_403_FORBIDDEN)
        name = request.data.get("name")
        password = request.data.get("password")
        team_join_attempt.send(sender=self.__class__, user=request.user, name=name)
        if name and password:
            try:
                team = get_object_or_404(Team, name=name)
                if team.password != password:
                    team_join_reject.send(sender=self.__class__, user=request.user, name=name)
                    raise FormattedException(m='invalid_team_password', status_code=HTTP_403_FORBIDDEN)
            except Http404:
                team_join_reject.send(sender=self.__class__, user=request.user, name=name)
                raise FormattedException(m='invalid_team', status_code=HTTP_404_NOT_FOUND)
            team_size = int(config.get('team_size'))
            if not request.user.is_staff and not team.size_limit_exempt and 0 < team_size <= team.members.count():
                return FormattedResponse(m='team_full', status=HTTP_403_FORBIDDEN)
            request.user.team = team
            request.user.save()
            team_join.send(sender=self.__class__, user=request.user, team=team)
            return FormattedResponse()
        return FormattedResponse(m='joined_team', status=HTTP_400_BAD_REQUEST)


class LeaveTeamView(APIView):
    """
    Remove the authenticated user from a team.
    """

    permission_classes = (IsAuthenticated & HasTeam & TeamsEnabled,)

    def post(self, request):
        if not config.get('enable_team_leave'):
            return FormattedResponse(m='leave_disabled', status=HTTP_403_FORBIDDEN)
        if Solve.objects.filter(solved_by=request.user).exists():
            return FormattedResponse(m='challenge_solved', status=HTTP_403_FORBIDDEN)
        if request.user.team.owner == request.user:
            if Member.objects.filter(team=request.user.team).count() > 1:
                return FormattedResponse(m='cannot_leave_team_ownerless', status=HTTP_403_FORBIDDEN)
            else:
                request.user.team.delete()
        request.user.team = None
        request.user.save()
        return FormattedResponse()

from asgiref.sync import async_to_sync
from channels.layers import get_channel_layer
from django.db.models.signals import post_save
from django.dispatch import receiver

from announcements.models import Announcement
from announcements.serializers import AnnouncementSerializer
from backend.signals import flag_score, flag_reject, use_hint, team_join
from config import config


def get_team_channel(user):
    return f'team.{user.team.id}'


def send(user, data):
    channel_layer = get_channel_layer()
    async_to_sync(channel_layer.group_send)(get_team_channel(user), data)


def broadcast(data):
    channel_layer = get_channel_layer()
    async_to_sync(channel_layer.group_send)('event', data)


@receiver(flag_score)
def on_flag_score(user, team, challenge, flag, solve, **kwargs):
    if not config.get('enable_solve_broadcast'):
        return
    broadcast({
        'type': 'send_json',
        'event_code': 1,
        'user': user.id,
        'username': user.username,
        'challenge_id': challenge.id,
        'challenge_name': challenge.name,
        'challenge_score': solve.score.points,
        'team': team.id,
        'team_name': team.name,
    })


@receiver(flag_reject)
def on_flag_reject(user, team, challenge, flag, **kwargs):
    send(user, {
        'type': 'send_json',
        'event_code': 2,
        'user': user.id,
        'username': user.username,
        'challenge_id': challenge.id,
        'challenge_name': challenge.name,
        'team': team.id,
        'team_name': team.name,
    })


@receiver(use_hint)
def on_use_hint(user, team, hint, **kwargs):
    send(user, {
        'type': 'send_json',
        'event_code': 3,
        'user': user.id,
        'username': user.username,
        'team': team.id,
        'team_name': team.name,
        'hint_name': hint.name,
        'hint_penalty': hint.penalty,
        'hint_text': hint.text,
        'challenge': hint.challenge.name,
    })


@receiver(team_join)
def on_team_join(user, team, **kwargs):
    send(user, {
        'type': 'send_json',
        'event_code': 4,
        'user': user.id,
        'username': user.username,
        'team': team.id,
        'team_name': team.name,
    })


@receiver(post_save, sender=Announcement)
def on_announcement_create(sender, instance, **kwargs):
    data = AnnouncementSerializer(instance).data
    data['type'] = 'send_json'
    data['event_code'] = 5
    broadcast(data)

import abc
import logging
import os
import shutil
import tarfile
from typing import Optional, Text, Tuple, TYPE_CHECKING

import rasa.shared.utils.common
import rasa.utils.common

if TYPE_CHECKING:
    from azure.storage.blob import ContainerClient

logger = logging.getLogger(__name__)


def get_persistor(name: Text) -> Optional["Persistor"]:
    """Returns an instance of the requested persistor.

    Currently, `aws`, `gcs`, `azure` and providing module paths are supported remote
    storages.
    """
    if name == "aws":
        return AWSPersistor(
            os.environ.get("BUCKET_NAME"), os.environ.get("AWS_ENDPOINT_URL")
        )
    if name == "gcs":
        return GCSPersistor(os.environ.get("BUCKET_NAME"))

    if name == "azure":
        return AzurePersistor(
            os.environ.get("AZURE_CONTAINER"),
            os.environ.get("AZURE_ACCOUNT_NAME"),
            os.environ.get("AZURE_ACCOUNT_KEY"),
        )
    if name:
        try:
            persistor = rasa.shared.utils.common.class_from_module_path(name)
            return persistor()
        except ImportError:
            raise ImportError(
                f"Unknown model persistor {name}. Please make sure to "
                "either use an included model persistor (`aws`, `gcs` "
                "or `azure`) or specify the module path to an external "
                "model persistor."
            )
    return None


class Persistor(abc.ABC):
    """Store models in cloud and fetch them when needed."""

    def persist(self, model_directory: Text, model_name: Text) -> None:
        """Uploads a model persisted in the `target_dir` to cloud storage."""
        if not os.path.isdir(model_directory):
            raise ValueError(f"Target directory '{model_directory}' not found.")

        file_key, tar_path = self._compress(model_directory, model_name)
        self._persist_tar(file_key, tar_path)

    def retrieve(self, model_name: Text, target_path: Text) -> None:
        """Downloads a model that has been persisted to cloud storage."""
        tar_name = model_name

        if not model_name.endswith("tar.gz"):
            # ensure backward compatibility
            tar_name = self._tar_name(model_name)

        self._retrieve_tar(tar_name)
        self._decompress(os.path.basename(tar_name), target_path)

    @abc.abstractmethod
    def _retrieve_tar(self, filename: Text) -> Text:
        """Downloads a model previously persisted to cloud storage."""
        raise NotImplementedError

    @abc.abstractmethod
    def _persist_tar(self, filekey: Text, tarname: Text) -> None:  # noqa: F841
        """Uploads a model persisted in the `target_dir` to cloud storage."""
        raise NotImplementedError

    def _compress(self, model_directory: Text, model_name: Text) -> Tuple[Text, Text]:
        """Creates a compressed archive and returns key and tar."""
        import tempfile

        dirpath = tempfile.mkdtemp()
        base_name = self._tar_name(model_name, include_extension=False)
        tar_name = shutil.make_archive(
            os.path.join(dirpath, base_name),
            "gztar",
            root_dir=model_directory,
            base_dir=".",
        )
        file_key = os.path.basename(tar_name)
        return file_key, tar_name

    @staticmethod
    def _tar_name(model_name: Text, include_extension: bool = True) -> Text:

        ext = ".tar.gz" if include_extension else ""
        return f"{model_name}{ext}"

    @staticmethod
    def _decompress(compressed_path: Text, target_path: Text) -> None:

        with tarfile.open(compressed_path, "r:gz") as tar:
            tar.extractall(target_path)  # target dir will be created if it not exists


class AWSPersistor(Persistor):
    """Store models on S3.

    Fetches them when needed, instead of storing them on the local disk."""

    def __init__(
        self,
        bucket_name: Text,
        endpoint_url: Optional[Text] = None,
        region_name: Optional[Text] = None,
    ) -> None:
        import boto3

        super().__init__()
        self.s3 = boto3.resource(
            "s3", endpoint_url=endpoint_url, region_name=region_name
        )
        self._ensure_bucket_exists(bucket_name, region_name)
        self.bucket_name = bucket_name
        self.bucket = self.s3.Bucket(bucket_name)

    def _ensure_bucket_exists(
        self, bucket_name: Text, region_name: Optional[Text] = None
    ) -> None:
        import boto3
        import botocore

        if not region_name:
            region_name = boto3.DEFAULT_SESSION.region_name

        bucket_config = {"LocationConstraint": region_name}
        # noinspection PyUnresolvedReferences
        try:
            self.s3.create_bucket(
                Bucket=bucket_name, CreateBucketConfiguration=bucket_config
            )
        except botocore.exceptions.ClientError:
            pass  # bucket already exists

    def _persist_tar(self, file_key: Text, tar_path: Text) -> None:
        """Uploads a model persisted in the `target_dir` to s3."""

        with open(tar_path, "rb") as f:
            self.s3.Object(self.bucket_name, file_key).put(Body=f)

    def _retrieve_tar(self, model_path: Text) -> None:
        """Downloads a model that has previously been persisted to s3."""
        tar_name = os.path.basename(model_path)
        with open(tar_name, "wb") as f:
            self.bucket.download_fileobj(model_path, f)


class GCSPersistor(Persistor):
    """Store models on Google Cloud Storage.

    Fetches them when needed, instead of storing them on the local disk."""

    def __init__(self, bucket_name: Text) -> None:
        from google.cloud import storage

        super().__init__()

        self.storage_client = storage.Client()
        self._ensure_bucket_exists(bucket_name)

        self.bucket_name = bucket_name
        self.bucket = self.storage_client.bucket(bucket_name)

    def _ensure_bucket_exists(self, bucket_name: Text) -> None:
        from google.cloud import exceptions

        try:
            self.storage_client.create_bucket(bucket_name)
        except exceptions.Conflict:
            # bucket exists
            pass

    def _persist_tar(self, file_key: Text, tar_path: Text) -> None:
        """Uploads a model persisted in the `target_dir` to GCS."""

        blob = self.bucket.blob(file_key)
        blob.upload_from_filename(tar_path)

    def _retrieve_tar(self, target_filename: Text) -> None:
        """Downloads a model that has previously been persisted to GCS."""

        blob = self.bucket.blob(target_filename)
        blob.download_to_filename(target_filename)


class AzurePersistor(Persistor):
    """Store models on Azure"""

    def __init__(
        self, azure_container: Text, azure_account_name: Text, azure_account_key: Text
    ) -> None:
        from azure.storage.blob import BlobServiceClient

        super().__init__()

        self.blob_service = BlobServiceClient(
            account_url=f"https://{azure_account_name}.blob.core.windows.net/",
            credential=azure_account_key,
        )

        self._ensure_container_exists(azure_container)
        self.container_name = azure_container

    def _ensure_container_exists(self, container_name: Text) -> None:
        from azure.core.exceptions import ResourceExistsError

        try:
            self.blob_service.create_container(container_name)
        except ResourceExistsError:
            # no need to create the container, it already exists
            pass

    def _container_client(self) -> "ContainerClient":
        return self.blob_service.get_container_client(self.container_name)

    def _persist_tar(self, file_key: Text, tar_path: Text) -> None:
        """Uploads a model persisted in the `target_dir` to Azure."""
        with open(tar_path, "rb") as data:
            self._container_client().upload_blob(name=file_key, data=data)

    def _retrieve_tar(self, target_filename: Text) -> None:
        """Downloads a model that has previously been persisted to Azure."""
        blob_client = self._container_client().get_blob_client(target_filename)

        with open(target_filename, "wb") as blob:
            download_stream = blob_client.download_blob()
            blob.write(download_stream.readall())

